import sys

# Notification interface
class Notification:
    def notificationBySms(self):
        pass

    def notificationByEmail(self):
        pass

    def notificationByCourier(self):
        pass

# Icici class implementing Notification interface
class Icici(Notification):
    def notificationBySms(self):
        print("ICICI - Notification By SMS")

    def notificationByEmail(self):
        print("ICICI - Notification By Email")

    def notificationByCourier(self):
        print("ICICI - Notification By Courier")

# Hdfc class implementing Notification interface
class Hdfc(Notification):
    def notificationBySms(self):
        print("HDFC - Notification By SMS")

    def notificationByEmail(self):
        print("HDFC - Notification By Email")

    def notificationByCourier(self):
        print("HDFC - Notification By Courier")

# BankFactory class
class BankFactory:
    def getIcici(self):
        return Icici()

    def getHdfc(self):
        return Hdfc()

def main():
    try:
        data = sys.stdin.read().strip()
        if not data:
            print("Invalid input")
            return

        parts = data.split()
        if len(parts) < 2:
            print("Invalid input")
            return

        try:
            bank = int(parts[0])
            notif = int(parts[1])
        except ValueError:
            print("Invalid input")
            return

        if bank not in (1, 2) or notif not in (1, 2, 3):
            print("Invalid input")
            return

        factory = BankFactory()

        if bank == 1:
            obj = factory.getIcici()
        else:
            obj = factory.getHdfc()

        if notif == 1:
            obj.notificationBySms()
        elif notif == 2:
            obj.notificationByEmail()
        elif notif == 3:
            obj.notificationByCourier()

    except Exception:
        print("Invalid input")

if __name__ == "__main__":
    main()
